    96	 * pilastras (`pilasters`) y los tabiques y queda al menos a 0,6 m de las del piso de abajo (`below`). */
    97	export function classrooms(pilasters: readonly number[], from: number, to: number, seed: number, door: number,
    98	  below: number[] = []): Rooms {
    99	  const weights = Array.from({ length: ROOMS_PER_FLOOR }, (_, i) => 1 + 0.3 * Math.sin(seed * 1.7 + i * 2.39));
