  3090	/** Une las piezas estáticas por material: miles de cajas pasan a pocas llamadas de dibujo. */
  3091	function mergeByMaterial(root: T.Group) {
  3092	  root.updateMatrixWorld(true);
  3093	  const inverse = root.matrixWorld.clone().invert();
  3094	  const buckets = new Map<T.Material, Map<number, T.BufferGeometry[]>>(), merged: T.Object3D[] = [];
  3095	  root.traverse((o) => {
  3096	    if (!(o instanceof T.Mesh) || o instanceof T.InstancedMesh || o.userData.keep || Array.isArray(o.material)
  3097	      || o.material.transparent) return;
  3098	    let geo = (o.geometry.index ? o.geometry.toNonIndexed() : o.geometry.clone()) as T.BufferGeometry;
  3099	    for (const name of Object.keys(geo.attributes)) if (!["position", "normal", "uv"].includes(name)) geo.deleteAttribute(name);
  3100	    if (!geo.attributes.normal) geo.computeVertexNormals();
  3101	    if (!geo.attributes.uv) geo.setAttribute("uv", new T.Float32BufferAttribute(new Float32Array(geo.attributes.position.count * 2), 2));
  3102	    geo = geo.applyMatrix4(new T.Matrix4().multiplyMatrices(inverse, o.matrixWorld));
  3103	    const flags = (o.castShadow ? 1 : 0) | (o.receiveShadow ? 2 : 0);
  3104	    let byShadow = buckets.get(o.material);
  3105	    if (!byShadow) buckets.set(o.material, byShadow = new Map());
  3106	    const batch = byShadow.get(flags);
  3107	    if (batch) batch.push(geo); else byShadow.set(flags, [geo]);
  3108	    merged.push(o);
  3109	  });
  3110	  for (const o of merged) o.parent?.remove(o);
