    52	    const x = sample() * size, y = sample() * size;
    53	    const radius = 13 + sample() * 18;
    54	    const tint = i % 2 ? "148,159,104" : "81,102,62";
    55	    const wrapX = x < radius ? size : x > size - radius ? -size : 0;
    56	    const wrapY = y < radius ? size : y > size - radius ? -size : 0;
    57	    for (const sx of wrapX ? [0, wrapX] : [0]) for (const sy of wrapY ? [0, wrapY] : [0]) {
    58	      const cx = x + sx, cy = y + sy;
    59	      const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
    60	      gradient.addColorStop(0, `rgba(${tint},0.16)`);
    61	      gradient.addColorStop(0.65, `rgba(${tint},0.05)`);
    62	      gradient.addColorStop(1, `rgba(${tint},0)`);
