     9	export function insidePolygon(point: Point, polygon: readonly Point[]) {
    10	  let inside = false;
    11	  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    12	    const [x, z] = polygon[i], [px, pz] = polygon[j];
    13	    if ((z > point[1]) !== (pz > point[1]) &&
    14	      point[0] < ((px - x) * (point[1] - z)) / (pz - z) + x) inside = !inside;
    15	  }
    16	  return inside;
    17	}
    18	
    19	export function distanceToSegment(point: Point, a: Point, b: Point) {
    20	  const dx = b[0] - a[0], dz = b[1] - a[1];
    21	  const t = Math.max(0, Math.min(1,
    22	    ((point[0] - a[0]) * dx + (point[1] - a[1]) * dz) / (dx * dx + dz * dz || 1)));
    23	  return Math.hypot(point[0] - a[0] - t * dx, point[1] - a[1] - t * dz);
    24	}
    25	
    26	export function footprintPose(id: string) {
    27	  const p = sectorBuildings.find((b) => b.id === id)!.points.slice(0, 4);
    28	  if (p[1][0] < p[0][0]) p.push(...p.splice(0, 2));
    29	  const x = p.reduce((s, q) => s + q[0], 0) / 4;
    30	  const z = p.reduce((s, q) => s + q[1], 0) / 4;
    31	  return {
    32	    x, z,
    33	    angle: Math.atan2(p[1][1] - p[0][1], p[1][0] - p[0][0]),
    34	    length: Math.hypot(p[1][0] - p[0][0], p[1][1] - p[0][1]),
    35	    width: Math.hypot(p[2][0] - p[1][0], p[2][1] - p[1][1]),
    36	  };
    37	}
    38	
    39	/** Centro y orientación de la huella OSM del Bloque 1 (75,0 × 13,4 m). */
    40	export const facultyPose = footprintPose(FACULTY_MAIN);
    41	
    42	/** Plano de CyT (metros, centro de la huella OSM del Bloque 1) → mundo. Solo gira y traslada: las medidas del
    43	 * plano se conservan; no se estira hacia la huella OSM. */
    44	export function facultyToWorld(position: readonly number[]): [number, number, number] {
    45	  const p = facultyPose, x = position[0], z = position[2];
    46	  return [p.x + x * Math.cos(p.angle) - z * Math.sin(p.angle), position[1],
    47	    p.z + x * Math.sin(p.angle) + z * Math.cos(p.angle)];
    48	}
    49	
    50	// Contorno de presentación en metros del plano de CyT.
    51	const perimeterCorners = [[-45, -12], [-36, -24], [-14, -32], [14, -53], [51, -75],
    52	  [94, -91], [113, -74], [134, -44], [144, -15], [145, 12], [128, 35], [94, 47],
    53	  [69, 57], [46, 73], [20, 83], [-19, 75], [-35, 54], [-46, 23]];
    54	const perimeter = perimeterCorners.flatMap(([x, z], i) => {
    55	  const [px, pz] = perimeterCorners.at(i - 1)!;
    56	  const [nx, nz] = perimeterCorners[(i + 1) % perimeterCorners.length];
    57	  const a = [x + (px - x) * 0.23, z + (pz - z) * 0.23];
    58	  const b = [x + (nx - x) * 0.23, z + (nz - z) * 0.23];
    59	  return Array.from({ length: 5 }, (_, step) => {
    60	    const t = step / 4, s = 1 - t;
    61	    const [worldX, , worldZ] = facultyToWorld([
    62	      s * s * a[0] + 2 * s * t * x + t * t * b[0], 0,
    63	      s * s * a[1] + 2 * s * t * z + t * t * b[1],
    64	    ]);
    65	    return [worldX, worldZ];
    66	  });
    67	});
