    71	export const campusBounds = {
    72	  minX: Math.min(...perimeterX) - 12,
    73	  maxX: Math.max(...perimeterX) + 12,
    74	  minZ: Math.min(...perimeterZ) - 12,
    75	  maxZ: Math.max(...perimeterZ) + 12,
    76	};
