    78	export function mapPercent(position: readonly number[]) {
    79	  return {
    80	    left: ((position[0] - campusBounds.minX) / (campusBounds.maxX - campusBounds.minX)) * 100,
    81	    top: ((position[2] - campusBounds.minZ) / (campusBounds.maxZ - campusBounds.minZ)) * 100,
    82	  };
    83	}

