     5	import { facultyPose } from "../data/campus-geometry";
     6	
     7	export function createCampus() {
     8	  const grass = makeGrassMaterial();
     9	  const faculty = createFaculty(grass), context = createCampusContext(grass);
    10	  const group = new T.Group(), colliders = new T.Group();
    11	  const pose = facultyPose;
    12	  // Igual que facultyToWorld: giro y traslación, sin escala, para conservar las medidas.
    13	  const matrix = new T.Matrix4().compose(
    14	    new T.Vector3(pose.x, 0, pose.z),
    15	    new T.Quaternion().setFromAxisAngle(new T.Vector3(0, 1, 0), -pose.angle),
    16	    new T.Vector3(1, 1, 1),
    17	  );
    18	  faculty.group.applyMatrix4(matrix);
    19	  faculty.colliders.applyMatrix4(matrix);
    20	  group.add(context.group, faculty.group);
    21	  colliders.add(context.colliders, faculty.colliders);
    22	  function setDetail(detail: boolean) {
    23	    faculty.group.visible = true;
    24	    context.group.children.forEach((mesh) => {
    25	      if (mesh.userData.contextLabel) mesh.visible = !detail;
    26	    });
    27	  }
    28	  setDetail(false);
    29	  group.updateMatrixWorld(true); colliders.updateMatrixWorld(true);
    30	  return { group, colliders, boundary: context.boundary, markers: faculty.markers, elevator: faculty.elevator, setDetail };
    31	}

