     8	/** Conversión inversa exacta: Mundo 3D → Coordenadas locales del Plano CyT */
     9	export function worldToFaculty(worldPos: readonly [number, number, number] | T.Vector3): [number, number, number] {
    10	  const wx = "x" in worldPos ? worldPos.x : worldPos[0];
    11	  const wy = "y" in worldPos ? worldPos.y : worldPos[1];
    12	  const wz = "z" in worldPos ? worldPos.z : worldPos[2];
    13	  const p = facultyPose;
    14	  const dx = wx - p.x;
    15	  const dz = wz - p.z;
    16	  const cos = Math.cos(p.angle);
    17	  const sin = Math.sin(p.angle);
    18	  return [
    19	    dx * cos + dz * sin,
    20	    wy,
    21	    -dx * sin + dz * cos,
    22	  ];
    23	}
