    55	    if (!this.moving && floor === this.floor) {
    56	      this.phase = this.opening >= 1 ? "open" : "opening";
    57	      this.elapsed = 0;
    58	      return;
    59	    }
    60	    if ((this.moving && floor === this.destination) || this.queue.includes(floor)) return;
    61	    this.queue.push(floor);
    62	    if (fromCabin && this.phase !== "idle" && !this.moving) this.phase = "closing";
    63	  }
    64	
    65	  update(dt: number) {
    66	    switch (this.phase) {
    67	      case "idle": {
    68	        const next = this.queue.shift();
    69	        if (next === undefined) return;
    70	        this.destination = next;
    71	        if (next === this.floor) {
    72	          this.phase = "opening";
    73	        } else {
    74	          this.elapsed = 0;
    75	          this.duration = 1.1 + Math.abs(next - this.floor) * this.floorHeight / 1.7;
    76	          this.phase = "moving";
    77	        }
    78	        break;
    79	      }
    80	      case "opening":
    81	        this.opening = Math.min(1, this.opening + dt / 0.65);
    82	        if (this.opening === 1) {
    83	          this.phase = "open";
    84	          this.elapsed = 0;
    85	        }
    86	        break;
    87	      case "open":
    88	        this.elapsed += dt;
    89	        if (this.elapsed >= 10) this.phase = "closing";
    90	        break;
    91	      case "closing":
    92	        this.opening = Math.max(0, this.opening - dt / 0.65);
    93	        if (this.opening === 0) this.phase = "idle";
    94	        break;
    95	      case "moving": {
    96	        this.elapsed += dt;
    97	        const t = Math.min(1, this.elapsed / this.duration);
    98	        // Quintic smoothstep: arranque y frenado graduales.
    99	        const progress = t * t * t * (10 + t * (-15 + 6 * t));
   100	        this.height = T.MathUtils.lerp(this.floor, this.destination, progress) * this.floorHeight;
   101	        if (t === 1) {
   102	          this.floor = this.destination;
   103	          this.phase = "opening";
   104	        }
   105	        break;
   106	      }
   107	    }
   108	  }
