     1	import { facultyBlueprint as plan, fromRect, PLAZA_LEVEL, type Vec2 } from "./faculty-blueprint.ts";
     2	
     3	// Coordenadas locales de cantina; alturas absolutas sobre el suelo del campus.
     4	const beds = [[-12, 16, 10, 28], [9.5, 15.5, -6, 10]] as const;
     5	const transition = 10;
     6	export function inCantina([x, z]: Vec2): Vec2 {
     7	  const { center, angle } = plan.cantina, dx = x - center[0], dz = z - center[1];
     8	  return [dx * Math.cos(angle) + dz * Math.sin(angle), -dx * Math.sin(angle) + dz * Math.cos(angle)];
     9	}
    10	const walk = plan.bedeliaWalk;
    11	const levelStrips = [
    12	  { a: inCantina(plan.bedeliaLawnEdge[0]), b: inCantina(plan.bedeliaLawnEdge[1]), margin: 1.3 },
    13	  { a: inCantina(fromRect(walk, [-walk.size[0] / 2, 0])), b: inCantina(fromRect(walk, [walk.size[0] / 2, 0])),
    14	    margin: walk.size[1] / 2 + 0.8 },
    15	];
    16	// Fuera del sendero, el césped recupera gradualmente la altura del jardín.
    17	const blend = 7;
    18	export const coveredWalkSurface = { width: 1.65, endHeight: 0.05, controlLift: 0.08 } as const;
    19	const [coveredStart, coveredEnd] = plan.coveredWalk.map(inCantina);
    20	const coveredDX = coveredEnd[0] - coveredStart[0], coveredDZ = coveredEnd[1] - coveredStart[1];
    21	const coveredLengthSquared = coveredDX ** 2 + coveredDZ ** 2;
    22	const bounds = [...beds, ...levelStrips.map(({ a, b, margin }) => [
    23	  Math.min(a[0], b[0]) - margin, Math.max(a[0], b[0]) + margin,
    24	  Math.min(a[1], b[1]) - margin, Math.max(a[1], b[1]) + margin,
    25	])];
    26	export const gardenBounds = {
    27	  minX: Math.floor(Math.min(...bounds.map((r) => r[0])) - transition - 1),
    28	  maxX: Math.ceil(Math.max(...bounds.map((r) => r[1])) + transition + 1),
    29	  minZ: Math.floor(Math.min(...bounds.map((r) => r[2])) - transition - 1),
    30	  maxZ: Math.ceil(Math.max(...bounds.map((r) => r[3])) + transition + 1),
    31	};
    32	export function gardenHeight(x: number, z: number): number {
    33	  const rise = Math.max(...beds.map(([x0, x1, z0, z1]) => {
    34	    const distance = Math.hypot(Math.max(x0 - x, 0, x - x1), Math.max(z0 - z, 0, z - z1));
    35	    const t = Math.max(0, 1 - distance / transition);
    36	    return PLAZA_LEVEL * t * t * (3 - 2 * t);
    37	  }));
    38	  // Jardín 45 cm bajo el pavimento; bordes a 8 mm del suelo, sin aristas suspendidas.
    39	  let height = Math.min(rise, PLAZA_LEVEL - 0.45) + 0.008;
    40	  for (const { a, b, margin } of levelStrips) {
    41	    const dx = b[0] - a[0], dz = b[1] - a[1];
    42	    const t = Math.max(0, Math.min(1, ((x - a[0]) * dx + (z - a[1]) * dz) / (dx * dx + dz * dz)));
    43	    const distance = Math.hypot(x - a[0] - t * dx, z - a[1] - t * dz);
    44	    const weight = 1 - Math.max(0, Math.min(1, (distance - margin) / blend));
    45	    height = Math.max(height, (PLAZA_LEVEL - 0.01) * weight * weight * (3 - 2 * weight));
    46	  }
    47	  // El terraplén de cantina llega hasta el caminero. Rebajarlo bajo el ancho
    48	  // completo, con margen para la interpolación de la malla de césped.
    49	  const t = Math.max(0, Math.min(1,
    50	    ((x - coveredStart[0]) * coveredDX + (z - coveredStart[1]) * coveredDZ) / coveredLengthSquared));
    51	  const distance = Math.hypot(x - coveredStart[0] - t * coveredDX, z - coveredStart[1] - t * coveredDZ);
    52	  const blendToLawn = Math.max(0, Math.min(1, (distance - coveredWalkSurface.width / 2 - 0.75) / 2));
    53	  const startHeight = plan.plazaGallery.smallSteps.bottom;
    54	  const pavement = startHeight * (1 - t) + coveredWalkSurface.endHeight * t
    55	    + 3 * coveredWalkSurface.controlLift * t * (1 - t);
    56	  const cut = Math.max(0, height - (pavement - 0.03));
    57	  return height - cut * (1 - blendToLawn * blendToLawn * (3 - 2 * blendToLawn));
    58	}

