    60	/** Copas agrupadas y siluetas variadas con dos lotes de instancias para todo el perímetro. */
    61	function addPerimeterTrees(group: T.Group, edge: number[][], y: number) {
    62	  let seed = 5293;
    63	  const random = () => {
    64	    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    65	    return seed / 4294967296;
    66	  };
    67	  const trees: { x: number; z: number; height: number; spread: number; narrow: boolean }[] = [];
    68	  let remaining = 2;
    69	  for (let i = 0; i < edge.length; i++) {
    70	    const [x, z] = edge[i], [nextX, nextZ] = edge[(i + 1) % edge.length];
    71	    const length = Math.hypot(nextX - x, nextZ - z);
    72	    const dx = (nextX - x) / length, dz = (nextZ - z) / length;
    73	    while (remaining < length) {
    74	      const inset = 2.5 + random() * 2.3;
    75	      trees.push({ x: x + dx * remaining - dz * inset, z: z + dz * remaining + dx * inset,
    76	        height: 3.5 + random() * 4, spread: 1.25 + random() * 0.8, narrow: random() < 0.24 });
    77	      if (random() < 0.36) {
    78	        const secondInset = inset + 2.2;
    79	        trees.push({ x: x + dx * (remaining + 1.1) - dz * secondInset, z: z + dz * (remaining + 1.1) + dx * secondInset,
    80	          height: 2.4 + random() * 3.7, spread: 1.05 + random() * 0.72, narrow: random() < 0.18 });
    81	      }
    82	      remaining += 2.7 + random() * 2.5;
    83	    }
    84	    remaining -= length;
    85	  }
    86	
    87	  const trunkShape = new T.CylinderGeometry(0.11, 0.23, 1, 6);
    88	  const crownShape = new T.IcosahedronGeometry(1, 2);
    89	  const tips = crownShape.attributes.position;
    90	  for (let i = 0; i < tips.count; i++) {
    91	    const x = tips.getX(i), y = tips.getY(i), z = tips.getZ(i);
    92	    const relief = 1 + 0.09 * Math.sin(11 * x + 4 * z) * Math.cos(9 * y - 5 * z);
    93	    tips.setXYZ(i, x * relief, y * relief, z * relief);
    94	  }
    95	  crownShape.computeVertexNormals();
    96	  const trunks = new T.InstancedMesh(trunkShape, new T.MeshStandardMaterial({ color: "#564638", roughness: 1 }), trees.length);
    97	  const lobes = 7;
    98	  const crowns = new T.InstancedMesh(crownShape, new T.MeshStandardMaterial({ roughness: 1 }), trees.length * lobes);
    99	  trunks.name = "Troncos del perímetro";
   100	  crowns.name = "Copas del perímetro";
   101	  const dummy = new T.Object3D(), color = new T.Color();
   102	  trees.forEach(({ x, z, height, spread, narrow }, index) => {
   103	    dummy.rotation.set(0, 0, 0);
   104	    dummy.position.set(x, y + height * 0.25, z);
   105	    dummy.scale.set(height * 0.18, height * 0.5, height * 0.18);
   106	    dummy.updateMatrix();
   107	    trunks.setMatrixAt(index, dummy.matrix);
   108	
   109	    const hue = 0.21 + random() * 0.055, tone = 0.22 + random() * 0.11;
   110	    const heading = random() * 2 * Math.PI;
   111	    for (let i = 0; i < lobes; i++) {
   112	      const angle = heading + i * 2.4;
   113	      const radial = i === 0 ? 0 : spread * (0.45 + random() * 0.32) * (narrow ? 0.65 : 1);
   114	      const rise = i === 0 ? 0.79 : 0.48 + random() * 0.23;
   115	      const size = spread * (i === 0 ? 0.67 : 0.48 + random() * 0.26);
   116	      dummy.position.set(x + Math.cos(angle) * radial, y + height * rise, z + Math.sin(angle) * radial);
   117	      dummy.rotation.set(0, angle, 0);
   118	      dummy.scale.set(size, size * (narrow ? 1.55 : 0.94), size * 0.9);
   119	      dummy.updateMatrix();
   120	      const slot = index * lobes + i;
   121	      crowns.setMatrixAt(slot, dummy.matrix);
   122	      crowns.setColorAt(slot, color.setHSL(hue, 0.39, tone + (rise - 0.52) * 0.26, T.SRGBColorSpace));
   123	    }
   124	  });
   125	  trunks.computeBoundingSphere();
   126	  crowns.computeBoundingSphere();
   127	  group.add(trunks, crowns);
   128	}

