   142	  }
   143	  walk() {
   144	    if (this.active || this.capturePending) return;
   145	    this.enabled = true;
   146	    this.capturePending = true;
   147	    const request = ++this.captureRequest;
   148	    try {
   149	      const result = this.canvas.requestPointerLock();
   150	      result?.catch(() => this.captureFailed(request));
