   168	  }
   169	  update(dt: number) {
   170	    if (!this.enabled || !this.active) return;
   171	    const forward = new T.Vector3();
   172	    this.camera.getWorldDirection(forward);
   173	    forward.y = 0;
   174	    forward.normalize();
   175	    const side = forward.clone().cross(this.camera.up).normalize();
   176	    const direction = new T.Vector3();
   177	    if (this.keys.has("KeyW") || this.keys.has("ArrowUp"))
